-- ============================================================================
-- عنقود القنصليات السورية: توحيد وتصحيح (2026-08-05)
-- ============================================================================
-- أعلى عناقيد الموقع طلباً: 21 صفحة و3,657 قراءة. وكان أقلّها دقّة.
--
-- ثلاثة أخطاء وقائعية، مرتَّبة بحسب الضرر:
--
--   1) الصفحة الأكثر قراءة (1,518) تقول «انتظر فتح نظام حجز المواعيد
--      الإلكتروني عبر mofaex.gov.sy». صفحة الخدمات الإلكترونية في الوزارة
--      نفسها تقول إنّ النظام يعمل، بوّابةً وتطبيقاً باسم MOFA SY. أي أنّ
--      السطر كان يوقف 1,518 قارئاً بانتظار ما يعمل أصلاً.
--
--   2) ثلاث صفحات تنشر ثلاثة أرقام لرسم الجواز نفسه: 200 دولار، و«200
--      مستعجل / 400 عادي» (مقلوبة — المستعجل أرخص من العادي؟)، وحقل رسوم
--      يقول «300-800». والوزارة لا تنشر جدول رسوم أصلاً
--      (mofaex.gov.sy/consular-services يرجع 404)، فلا سند لأيٍّ منها.
--      النتيجة العملية: قارئ يسافر إلى عنتاب بمبلغ خاطئ.
--
--   3) صفحة توجّه حجز الجوازات إلى syrian-embassy.com — نطاق غير حكومي.
--      تُحذف كاملةً ولا يُنقل منها شيء.
--
-- وتناقض رابع في مقاس الصور: 4×6 في صفحة، و4×4 في صفحتين إحداهما تنقل
-- الدليل الإجرائي الذي نشرته القنصلية نفسها. يبقى 4×4 ويسقط 4×6، لكن
-- منسوباً إلى ما نشرته القنصلية لا إلى تحقّق منّا من الوزارة — والفرق
-- مكتوب في الصفحة لا مطموس.
--
-- ما يُدمج: 21 صفحة ← 15.
--   • عنتاب: 3 صفحات ← دليل واحد. الباقي هو الدليل لا الخبر: رابطه دائم
--     لا مؤرَّخ، وصفحة الخبر نفسها تُحيل إليه بوصفه «الدليل الدائم المحدّث».
--   • حجز الموعد: 3 ← 1.  • التصديق والوكالات: 2 ← 1.  • الجواز: 2 ← 1.
--
-- ما لا يُدمج ولكلٍّ سببه مكتوب في المولّد: تصديق تركيا←سوريا (اتجاه معاكس)،
-- جواز الأطفال، الجواز المفقود، السفارة التركية في بيروت، الأبوستيل التركي.
--
-- القاعدة: لا يُنقل عنصر إلا إن كان مسمّى صراحةً في المولّد، وكل تصحيح نصّي
-- يجب أن يطابق مرّة واحدة تماماً وإلا فشل التوليد — فلا تصحيح يمرّ بلا أثر.
--
-- شغّله بعد اكتمال نشر الشيفرة (التحويلات في next.config.ts).
-- ============================================================================

-- syrian-consulate-gaziantep-guide  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['تأكيد الموعد مطبوعاً من تطبيق (MOFA SY)', 'استمارة طلب الجواز مطبوعة بالألوان (لمعاملات الجوازات)', 'إخراج قيد مصدّق (من المختار والسلطة المحلية وشاهدَين، ومصدّق من وزارة الخارجية السورية أو المكاتب القنصلية)، أو هوية شخصية', 'صورتان شخصيتان بخلفية بيضاء ولباس داكن، قياس 4×4', 'نسخة عن بطاقة الإقامة أو الكيمليك في تركيا', 'الوثائق الخاصة بمعاملتك — أكّدها عند الحجز فهي تختلف بحسب الخدمة', 'جواز السفر السوري (حتى لو منتهي الصلاحية)']::text[],
    steps = ARRAY['نزّل تطبيق (MOFA SY) الرسمي من (Google Play) أو (App Store)', 'أنشئ حساباً ببياناتك الحقيقية كما في وثائقك', 'اختر البعثة: القنصلية العامة في غازي عنتاب، ثم نوع المعاملة', 'اختر موعداً متاحاً وأكّد الحجز', 'احفظ تأكيد الموعد واطبعه', 'راجع القنصلية في موعدك مع الأوراق كاملة، وادفع الرسوم داخل المقر فقط']::text[],
    tips = ARRAY['الحجز مجاني رسمياً — أي شخص يبيعك موعداً أو «دوراً» يخدعك', 'المواعيد تُفتح دفعات — تابع التطبيق بانتظام بدل الذهاب على أمل الطابور', 'القنصلية تخدم سوريّي ولايات الجنوب — غازي عنتاب وكلس وهاتاي وشانلي أورفا ومرسين وأضنة — بدل السفر إلى إسطنبول لإنجاز معاملة واحدة.', 'تأكد من نوع معاملتك بدقة قبل الحجز لأن الأوراق تختلف بين إصدار أول وتجديد وبدل فاقد', 'احتفظ بإيصالات أي رسوم تدفعها داخل القنصلية', 'القنصلية لا تقبل الدولار من الإصدارات القديمة — احمل العملة الجديدة حصراً.', 'الأطفال دون 12 سنة: لا بصمات، وحضور الأب أو الجدّ إلزامي؛ وعند غياب الأب تُطلب وصاية شرعية مصدّقة من داخل سوريا حصراً.', 'من 12 إلى 70 سنة: البصمات إلزامية.', 'فوق السبعين: الحضور الشخصي إلزامي، ولا إعفاء منه إلا بإثبات العجز بتقرير طبي معتمد صادر رسمياً من بلد الإقامة.', 'الدليل الإجرائي الذي نشرته القنصلية يذكر رسم 200 دولار للجواز العادي وصلاحية ست سنوات. وزارة الخارجية والمغتربين لا تنشر جدول رسوم على موقعها، فأكّد الرقم عند حجز موعدك ولا تعتمد على رقم من وسيط.']::text[],
    fees = 'الرسوم الرسمية تُعلَن عبر البوّابة الإلكترونية للوزارة (mofaex.gov.sy). تختلف الرسوم بحسب نوع الخدمة. لا توجد رسوم "تسريع" رسمية — أيّ طلب من هذا النوع غير قانوني.',
    source = 'وزارة الخارجية والمغتربين السورية (mofaex.gov.sy)، وكالة سانا الرسمية، تغطية تلفزيون سوريا، Hurriyet Daily News، بتاريخ 7-9 يونيو 2026.',
    last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-gaziantep-guide';

-- syrian-consulate-appointment  ←  2 صفحة
UPDATE articles SET
    documents = ARRAY['جواز السفر أو الهوية السورية', 'إيصال الموعد المطبوع', 'المستندات المطلوبة للخدمة القنصلية نفسها (تختلف حسب نوع المعاملة).']::text[],
    steps = ARRAY['الدخول للمنصة: قم بزيارة موقع القنصلية الإلكتروني.', 'إنشاء حساب: سجل الدخول أو أنشئ حساباً جديداً باستخدام بريدك الإلكتروني.', 'اختيار الخدمة: اختر نوع المعاملة (جواز سفر، تصديق، وكالة...).', 'اختيار الموعد: ابحث عن المواعيد المتاحة باللون الأخضر وقم بتأكيد الحجز.', 'طباعة الإيصال: اطبع إيصال الموعد واحتفظ بنسخة منه على هاتفك لإبرازه عند الدخول.', 'تأكّد أنّ رابط التحميل رسمي قبل إدخال أي بيانات — تنتشر روابط مزيفة باسم القنصلية.']::text[],
    tips = ARRAY['المواعيد تفتح عادة في أوقات عشوائية، تابع الموقع باستمرار.', 'احذر من السماسرة الذين يطلبون مبالغ ضخمة، الحجز مجاني رسمياً.', 'فعّل تنبيهات التطبيق كي لا يفوتك الموعد.']::text[],
    fees = 'الحجز نفسه عادةً مجاني؛ رسوم المعاملات القنصلية تختلف حسب نوع الخدمة ولوائح البعثة.',
    last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-appointment';

-- syrian-document-attestation  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['الوثيقة الأصلية المصدقة من الخارجية السورية', 'نسخة ضوئية عن الوثيقة', 'هوية صاحب العلاقة', 'نصّ الوكالة مطبوعاً (للوكالات)']::text[],
    steps = ARRAY['تصديق الخارجية: يجب أن تكون الوثيقة مصدقة من الخارجية في دمشق.', 'حجز موعد تصديق: احجز موعد (تصديق) في القنصلية.', 'الختم القنصلي: قدّم الوثيقة للقنصلية ليوضع الختم عليها. الرسم غير منشور رسمياً — أكّده عند حجز الموعد.', 'التصديق التركي: بعد الختم القنصلي تُصدَّق الوثيقة لدى الجهة التركية المختصة — تختلف بحسب الولاية ونوع الوثيقة، فاسأل ولاية إقامتك (Valilik) عن الجهة الصحيحة قبل التوجّه.', 'للوكالة: حضّر نصّها — يُفضَّل أن يكتبه محامٍ في سوريا ويُرسله إليك مطبوعاً.', 'الوكالة تتطلّب حضور الموكِّل شخصياً — لا تُقبل بالنيابة.', 'بعد الختم القنصلي تُرسل الوكالة بالبريد إلى سوريا لتصديقها من وزارة الخارجية هناك.']::text[],
    tips = ARRAY['بدون ختم القنصلية، لا يمكنك ترجمة وتنوتر الوثيقة السورية في تركيا.', 'الوكالة العامة خطيرة، يفضل دائماً التخصيص (لبيع عقار محدد مثلاً).', 'صلاحية الوكالة قد تكون محددة بـ 3 أشهر في بعض المعاملات.']::text[],
    title = 'تصديق الأوراق والوكالات في القنصلية السورية 2026',
    seo_title = 'تصديق الأوراق والوكالات في القنصلية السورية 2026',
    seo_description = 'تصديق وثيقة سورية للاستعمال في تركيا، وتنظيم وكالة وتصديقها — السلسلة كاملة من الخارجية السورية إلى القنصلية ثم الولاية، ومن يجب أن يحضر شخصياً.',
    last_update = CURRENT_DATE
WHERE slug = 'syrian-document-attestation';

-- syrian-passport-renewal  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['صورة حجز الموعد من تطبيق MOFA SY', 'استمارة جواز السفر مطبوعة من التطبيق — بالألوان إلزاماً', 'الجواز المطلوب تجديده', 'صورتان شخصيتان ملوّنتان 4×4، خلفية بيضاء وملابس داكنة', 'صورة الهوية أو إخراج القيد إن لم يكن الرقم الوطني على الجواز القديم', 'نسخة عن الإقامة أو الفيزا — شرط الحصول على مدة صلاحية طويلة']::text[],
    steps = ARRAY['احجز دوراً عبر تطبيق المواعيد MOFA SY أو بوابة mofaex.gov.sy/eservices-app.', 'اطبع الاستمارة بالألوان وجهّز الأوراق كاملة قبل يوم الموعد.', 'احضر شخصياً في الموعد إلى صالة التصديقات في البعثة وقدّم الثبوتيات.', 'أعطِ التوقيع والبصمة الإلكترونيَّين على منظومة الجوازات.', 'سدّد الرسم نقداً بالدولار (إصدار 2017 أو أحدث).', 'تحقق من تطابق الاسم وتاريخ الميلاد كما هو في الإقامة.', 'راجع الجهة المختصة لتحديث رقم الجواز في السجل إذا كان ذلك مطلوباً في ولايتك.']::text[],
    tips = ARRAY['افحص أوراق الدولار قبل الموعد: الشرط الرسمي هو إصدار 2017 أو أحدث، لا مجرد ورقة سليمة.', 'اطبع الاستمارة بالألوان — الطباعة بالأبيض والأسود سبب متكرّر لردّ المعاملة.', 'خذ نسخة عن إقامتك التركية حتى لو لم تُطلب: هي شرط مدة الصلاحية الطويلة.', 'البصمة إلزامية لمن بين 15 و70 عاماً، فلا يُغني الوكيل عن الحضور الشخصي.', 'إن كنت مقيماً خارج سوريا أكثر من 6 أشهر، أنجز التسجيل القنصلي أيضاً.', 'لا تنتظر موعد التجديد؛ أي اختلاف في رقم الجواز قد يسبب تعطيل معاملات.', 'احتفظ بالجواز القديم إن كان ذلك مسموحاً لأنه يساعد في مطابقة السجل.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'syrian-passport-renewal';

-- التصحيحات الوقائعية ----------------------------------------------------
UPDATE articles SET details = replace(details, '<li><p>تجديد الجواز: 200 $ مستعجل -400 $ عادي </p></li>', '<li><p>وزارة الخارجية والمغتربين السورية لا تنشر جدول رسوم على موقعها، والأرقام المتداولة متضاربة. الدليل الإجرائي الذي نشرته قنصلية غازي عنتاب يذكر <strong>200 دولار للجواز العادي وصلاحية ست سنوات</strong>؛ وما عدا ذلك أكّده عند حجز الموعد، ولا تعتمد على رقم من وسيط.</p></li>'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-services-turkey-2026';

UPDATE articles SET details = replace(details, '<h3>المدة:</h3><p>عادةً 3 ايام المستعجل - 1ل 2 أشهر العادي.</p>', '<h3>المدة:</h3><p>مدّة الإنجاز غير منشورة رسمياً وتختلف بحسب البعثة وضغط المواعيد — اسأل عنها عند تقديم معاملتك.</p>'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-services-turkey-2026';

UPDATE articles SET details = replace(details, '<li><p><strong>الرسوم:</strong> 200 دولار حسب النوع</p></li>', '<li><p><strong>الرسوم:</strong> غير منشورة رسمياً — تُؤكَّد عند حجز الموعد</p></li>'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-services-turkey-2026';

UPDATE articles SET fees = 'لا تنشر وزارة الخارجية والمغتربين السورية جدول رسوم قنصلية على موقعها الرسمي. الرقم الوحيد المنشور من جهة رسمية هو ما ورد في الدليل الإجرائي لقنصلية غازي عنتاب: 200 دولار للجواز العادي، وصلاحيته ست سنوات. أكّد رسم معاملتك عند حجز الموعد، وادفع داخل القنصلية فقط.', last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-services-turkey-2026';

UPDATE articles SET details = replace(details, '<li><p>صور شخصية حديثة (6 صور بخلفية بيضاء)</p></li>', '<li><p>صور شخصية بخلفية بيضاء — الدليل الإجرائي لقنصلية غازي عنتاب يطلب صورتين قياس 4×4، وقد يختلف العدد بحسب المعاملة والبعثة، فأكّده عند حجز الموعد</p></li>'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-services-turkey-2026';

UPDATE articles SET details = replace(details, '<li><p><strong>مرسين:</strong> مكتب قنصلي - لم يفتح بعد - </p></li>', '<li><p><strong>باقي المدن:</strong> دليل البعثات على موقع الوزارة لا يُدرج أي بعثة سورية أخرى في تركيا — لا سفارة في أنقرة ولا مكتب في مرسين أو إزمير أو أضنة (تحقّقنا منه في 5 آب/أغسطس 2026): <a href="/consulates">دليل القنصليات السورية في تركيا</a></p></li>'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-services-turkey-2026';

UPDATE articles SET details = replace(details, 'حتى تاريخ تحديث هذا الدليل لم تنشر وزارة الخارجية والمغتربين السورية عنوان شارع تفصيلياً على موقعها الرسمي، وتأكيد الموعد الذي يصلك عبر التطبيق الرسمي هو مرجعك لتفاصيل الحضور.', 'وقد نشرت وزارة الخارجية والمغتربين السورية العنوان في دليل بعثاتها الرسمي: منطقة Günevler، شارع kemal köker، بلدية şehitkamil، الرمز البريدي 27560 (تحقّقنا منه في 5 آب/أغسطس 2026). ويبقى تأكيد الموعد الذي يصلك عبر التطبيق مرجعك لتفاصيل الحضور.'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-gaziantep-guide';

UPDATE articles SET details = replace(details, 'لا يوجد عنوان شارع تفصيلي منشور رسمياً حتى الآن — اعتمد على تأكيد موعدك وقنوات الوزارة الرسمية.', 'والعنوان كما ينشره دليل البعثات الرسمي: منطقة Günevler، شارع kemal köker، بلدية şehitkamil، الرمز البريدي 27560 (تحقّقنا منه في 5 آب/أغسطس 2026).'), last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-gaziantep-guide';

UPDATE articles SET warning = 'لا دخول من دون موعد مؤكَّد عبر تطبيق (MOFA SY) أو بوّابة الوزارة. الوزارة لا تنشر رقم هاتف لهذه القنصلية حتى 5 آب/أغسطس 2026، وتنشر العنوان في دليل بعثاتها: منطقة Günevler، شارع kemal köker، بلدية şehitkamil، الرمز البريدي 27560. لا تعتمد على أرقام أو عناوين متداولة في أدلة قديمة أو حسابات غير رسمية، وأكّد الرسوم وتفاصيل معاملتك من قنوات وزارة الخارجية والمغتربين.', last_update = CURRENT_DATE
WHERE slug = 'syrian-consulate-gaziantep-guide';

-- الصفحات المدموجة تُحذف بعد نقل ما يستحقّ النقل
DELETE FROM articles WHERE slug IN ('gaziantep-syrian-consulate-opens-2026-06-11', 'alqnslya-alswrya-fy-ghazy-antab-mttlbat', 'syrian-consular-appointments-app', 'passport-booking-system-legacy', 'agency-attestation-legacy', 'identity-passport-renewal-update');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول أربعة صفوف، والثاني صفر، والثالث صفر
SELECT slug, coalesce(array_length(documents,1),0) AS docs,
       coalesce(array_length(steps,1),0) AS steps,
       coalesce(array_length(tips,1),0)  AS tips, last_update
FROM articles WHERE slug IN ('syrian-consulate-gaziantep-guide', 'syrian-consulate-appointment', 'syrian-document-attestation', 'syrian-passport-renewal') ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('gaziantep-syrian-consulate-opens-2026-06-11', 'alqnslya-alswrya-fy-ghazy-antab-mttlbat', 'syrian-consular-appointments-app', 'passport-booking-system-legacy', 'agency-attestation-legacy', 'identity-passport-renewal-update');

-- لا يبقى أي رقم رسوم غير مسنَد ولا رابط غير حكومي
SELECT slug FROM articles
WHERE details LIKE '%200 $ مستعجل%' OR details LIKE '%6 صور بخلفية%'
   OR details LIKE '%syrian-embassy.com%' OR fees LIKE '%300-800%';
